import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('las-facetas-del-yo-soy-vii-la-puerta-estrecha', 'C',
 [dict(t=10, e=58, titulo='La puerta estrecha es Cristo', txt='¿A quién le corresponde entrar por la puerta estrecha? A ustedes, hijos de Dios. Ustedes son los que van a entrar por la puerta estrecha, y la puerta es Cristo. Por eso no cualquiera entra en esa puerta. Hay puertas de perdición, hermano, que son grandotas: «ancha es la puerta y espacioso el camino que lleva a la perdición». Por eso muchas veces lo fácil no es. Tenga cuidado con lo que hace.'),
  dict(t=474, e=525, titulo='Por eso se estrecha la puerta', txt='Tocó la puerta de su corazón. Quiere decir que nosotros también tenemos una puerta que podemos abrir o cerrar. Entró en ti, te apuntaron en el libro de la vida, te perdonaron tus pecados y fuiste adoptado para ser hijo. Esa es una faceta. Pero el Señor, como estuvo tan contento contigo, no solo entra en ti, sino que te deja que entres en él. Por eso es que se estrecha la puerta, porque no vas a entrar a cualquier corazón: vas a entrar al corazón de Dios. Ahí no puede entrar cualquiera; van a entrar los hijos genuinos que desecharon el pecado, que soltaron la fornicación […].'),
  dict(t=2437, e=2490, titulo='Una noche para arrepentirse y afianzarse', txt='¿Cuántos saben que el camino está aquí hoy? ¿Cuántos saben que la verdad está aquí? ¿Y cuántos saben que Jesucristo le ha dado vida a usted? Esta es una noche para arrepentirse, pero también es una noche para afianzarse. Dígale: «Señor, yo me afianzo. Estaba teniendo dos pensamientos, pero hoy el Señor me ha fortalecido y me afianzo de ti, me afirmo, porque yo sí quiero decir la verdad. Yo sí quiero mostrarle a muchos el camino, en el nombre de Jesús».')],
 [dict(t=857, txt='Dios se levanta hoy para que pelees la buena batalla de la fe.'),
  dict(t=1305, txt='Hoy el Señor te quiere equilibrar, iglesia. No quiere que estés en muchos pensamientos, sino que estés en el pensamiento de Dios para lo que viene.'),
  dict(t=2527, txt='Hoy el Señor te está sacando de la inmundicia; hoy está limpiando tu corazón, tus oídos y tus ojos para que veas su gloria.')],
 ['¿Qué puertas «anchas y fáciles» necesitas cerrar esta semana para entrar por la puerta que es Cristo?',
  '¿Qué cosas que guardas necesitas entregar al Señor para pelear la buena batalla de la fe?',
  '¿En qué momentos tienes «dos pensamientos» y cómo puedes afianzarte hoy en el pensamiento de Dios?'])
